"""검사된 공유 CSV만 읽는 오프라인 데이터 확인 화면."""
import csv,json,html
from pathlib import Path
R=Path(__file__).resolve().parent;O=R/'shared/snapshot_20261027'
data=list(csv.DictReader((O/'records.csv').open(encoding='utf-8-sig')))
payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e')
template='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>현대차·LS ELECTRIC 데이터</title>
<style>*{box-sizing:border-box}body{margin:0;padding:32px;background:#f2f4f6;color:#191f28;font:15px -apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo",sans-serif}main{max-width:1200px;margin:auto}h1{font-size:30px;margin-bottom:12px}p{line-height:1.7}.filters{display:flex;flex-wrap:wrap;gap:10px}input,select,button{font:inherit;padding:11px;border:1px solid #d1d6db;border-radius:9px;background:white}button{background:#3182f6;color:white;cursor:pointer;border:0}section{padding:22px;background:white;border-radius:15px;margin:14px 0}.meta{display:flex;gap:14px;flex-wrap:wrap}.label{color:#1b64da;font-weight:700}.text{white-space:pre-wrap;line-height:1.7;margin:16px 0}small{color:#4e5968}a{color:#1b64da}#info{margin:20px 0}.stats{font-size:19px;font-weight:650}</style>
<main><h1>현대차 · LS ELECTRIC</h1><p class="stats">게시글 32,091건 · AI 분류 16,866건 · 미분류 15,225건</p><p>2026년 10월 27일 확보분을 고정한 팀 공유 자료입니다. 현대차 9/4~10/20, LS ELECTRIC 9/1~10/20.<br>목표 기간 전수 자료가 아니며 실제 답글은 포함하지 않습니다. 개인정보 위험 표현이 감지된 본문은 비웠습니다. 완전한 익명화를 보장하지 않습니다.<br>AI 라벨은 비공개 원문 기준이며, 사람 기준 정확도는 측정하지 않았습니다. 시세는 네이버 일봉입니다.</p>
<p><a href="records.csv" download>행별 데이터 CSV</a> · <a href="daily_summary.csv" download>거래일별 감성·주가 CSV</a> · <a href="manifest.json">수집 범위와 검사 정보</a></p>
<div class="filters"><select id="stock"><option value="">두 종목</option><option>현대차</option><option>LS ELECTRIC</option></select><select id="status"><option value="">전체 처리 상태</option><option value="classified">AI 분류 완료</option><option value="unclassified">미분류</option></select><select id="sent"><option value="">모든 감정</option><option>긍정</option><option>중립</option><option>부정</option><option>혼합</option><option>판단유보</option></select><input id="date" type="date"><input id="q" placeholder="공유 본문 검색"></div><div id="info"></div><div id="rows"></div><button id="more">50건 더 보기</button></main>
<script>const DATA=__DATA__;let limit=50;const el=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const pct=v=>v===''?'없음':(Number(v)>0?'+':'')+Number(v).toFixed(2)+'%';function render(){const a=DATA.filter(r=>(!el('stock').value||r.name===el('stock').value)&&(!el('status').value||r.classification_status===el('status').value)&&(!el('sent').value||r.sentiment===el('sent').value)&&(!el('date').value||r.created_date===el('date').value)&&(!el('q').value||r.text_norm.includes(el('q').value)));el('info').textContent=`전체 ${DATA.length.toLocaleString()}건 · 필터 ${a.length.toLocaleString()}건 · ${Math.min(limit,a.length)}건 표시`;el('rows').innerHTML=a.slice(0,limit).map(r=>`<section><div class="meta"><b>${esc(r.name)}</b><span>${esc(r.created_date)}</span><span class="label">${esc(r.sentiment||'미분류')}</span><small>${esc(r.relevance)}</small></div><div class="text">${r.text_status==='available'?esc(r.text_norm):'[개인정보 위험 표현 검사로 본문 비공개]'}</div><small>분석 거래일 ${esc(r.trading_date||'다음 시세 없음')} · 당일 등락 ${pct(r.same_day_return_pct)} · 다음 거래일 ${pct(r.next_day_return_pct)}</small></section>`).join('');el('more').hidden=limit>=a.length}for(const id of ['stock','status','sent','date','q'])el(id).addEventListener('input',()=>{limit=50;render()});el('more').onclick=()=>{limit+=50;render()};render();</script></html>'''
(O/'viewer.html').write_text(template.replace('__DATA__',payload))
print('Shared viewer:',len(data),'rows')
